            else:
                pivots = (x for x in self.payload if x < floor)
        else:
            pivots = self.payload
        for pivot in pivots:
            yield self.hook(pivot, a, b)

def time_to_get_free(payload, floor):
    if payload:
        lo, up = (min(payload), max(payload))
        return abs(lo - up) + min(abs(floor - lo), abs(floor - up))
    else:
        return 0

